const fs=require("node:fs"),cp=require("node:child_process"),crypto=require("node:crypto");
const kind=process.argv[2],cwd="/Users/julianhein/.codex/worktrees/c9fb/r-dcc-units/dcc1",prefix=cwd+"/docs/coordinator/worktree-completion/evidence/dcc1-parity-observer-"+kind;
const rawPath=prefix+".raw.log",metaPath=prefix+".meta.jsonl";
for(const p of [rawPath,metaPath])if(fs.existsSync(p))throw Error("refusing overwrite "+p);
const captureBlob=cp.execFileSync("git",["hash-object","tests/parity/helpers/capture.ts"],{cwd,encoding:"utf8"}).trim();
if(captureBlob!=="31776c251399a9b945822c7d796b44468fb6cadd")throw Error("instrumented blob changed");
const index=cp.execFileSync("git",["write-tree"],{cwd,encoding:"utf8"}).trim();
if(index!=="ae00723e05d20a6c87d0ada500fc77a456870ea9")throw Error("index changed");
const raw=fs.openSync(rawPath,"wx",0o600),meta=fs.openSync(metaPath,"wx",0o600);
const args=["-k","-t","45","/tmp/hr-worktree-light-gate.lock","npm","run",kind],start=new Date().toISOString(),mono=process.hrtime.bigint();
const errors=[];let bytes=0;const digest=crypto.createHash("sha256");
function write(fd,b){let n=0;while(n<b.length)n+=fs.writeSync(fd,b,n,b.length-n);fs.fsyncSync(fd)}
function record(v){write(meta,Buffer.from(JSON.stringify(v)+"\n"))}
record({event:"start",classification:"Annotated process metadata; raw log contains child stdout/stderr bytes in observed callback order",command:"/usr/bin/lockf "+args.join(" "),executable:"/usr/bin/lockf",args,cwd,start,captureBlob,index,environment:"Inherited; no environment modifications for the approved light command",rawPath,metaPath});
const child=cp.spawn("/usr/bin/lockf",args,{cwd,env:process.env,stdio:["ignore","pipe","pipe"]});
record({event:"spawn",pid:child.pid,at:new Date().toISOString()});
function capture(b,channel){try{write(raw,b);bytes+=b.length;digest.update(b)}catch(e){errors.push({phase:"raw-write",message:String(e)})}process[channel].write(b)}
child.stdout.on("data",b=>capture(b,"stdout"));child.stderr.on("data",b=>capture(b,"stderr"));
child.on("error",e=>errors.push({phase:"spawn",message:String(e)}));
child.on("close",(gateExit,signal)=>{try{fs.fsyncSync(raw);fs.closeSync(raw)}catch(e){errors.push({phase:"raw-close",message:String(e)})}
const terminal={event:"terminal",gateExit,signal,loggerExit:errors.length?1:0,errors,start,end:new Date().toISOString(),elapsedSeconds:Number(process.hrtime.bigint()-mono)/1e9,rawBytes:bytes,rawSha256:digest.digest("hex"),captureBlob,index};
try{record(terminal);fs.closeSync(meta)}catch(e){terminal.loggerExit=1;terminal.errors.push({phase:"meta-terminal",message:String(e)})}
process.stdout.write("\nLOGGER_TERMINAL "+JSON.stringify(terminal)+"\n");process.exitCode=gateExit===0?terminal.loggerExit:(gateExit===null?1:gateExit);
});
